725	func formatCommitDate(dateStr string) string {
726		t, err := time.ParseInLocation("2006-01-02", dateStr, time.Local)
727		if err != nil {
728			return dateStr
729		}
730		now := time.Now().Local()
731		today := time.Date(now.Year(), now.Month(), now.Day(), 0, 0, 0, 0, now.Location())
732		days := int(today.Sub(t).Hours() / 24)
733	
734		switch days {
735		case 0:
736			return t.Format("Monday 2 Jan") + " (today)"
737		case 1:
738			return t.Format("Monday 2 Jan") + " (yesterday)"
739		default:
740			return t.Format("Monday 2 Jan")
741		}
742	}
