752	func truncateDisplayWidth(s string, width int, tail string) string {
753		if lipgloss.Width(s) <= width {
754			return s
755		}
756		if width <= 0 {
757			return ""
758		}
759		if lipgloss.Width(tail) >= width {
760			return tail[:width]
761		}
762	
763		var b strings.Builder
764		remaining := width - lipgloss.Width(tail)
765		for _, r := range s {
766			if lipgloss.Width(b.String()+string(r)) > remaining {
767				break
768			}
769			b.WriteRune(r)
770		}
771		return b.String() + tail
772	}
